import { OpenAIChat } from "../protocols/openai-chat.js";
import { OpenAIImages } from "../protocols/openai-images.js";
import { OpenResponses } from "../protocols/open-responses.js";
import { SystemOne } from "../protocols/system-one.js";
import { cacheControl } from "../protocols/utils/cache.js";
import { AuthOptions } from "../route/auth-options.js";
import { Route } from "../route/client.js";
import { Endpoint } from "../route/endpoint.js";
import { MediaRoute } from "../route/media.js";
import { Protocol } from "../route/protocol.js";
import { ProviderID } from "../schema/index.js";
export const id = ProviderID.make("digitalocean");
const baseURL = "https://inference.do-ai.run/v1";
export const protocol = Protocol.make({
    id: "digitalocean-chat",
    body: {
        schema: OpenAIChat.protocol.body.schema,
        from: (request) => OpenAIChat.fromRequest(request, { cacheControl: cacheControl() }),
    },
    stream: OpenAIChat.protocol.stream,
});
export const route = Route.make({
    id: "digitalocean",
    provider: id,
    providerMetadataKey: "digitalocean",
    protocol,
    endpoint: Endpoint.path("/chat/completions", { baseURL }),
    framing: OpenAIChat.framing,
});
const responsesRoute = Route.make({
    id: "digitalocean-responses",
    provider: id,
    providerMetadataKey: "digitalocean",
    protocol: OpenResponses.protocol,
    endpoint: Endpoint.path("/responses", { baseURL }),
    transport: OpenResponses.httpTransport,
    defaults: { providerOptions: { store: false, include: ["reasoning.encrypted_content"] } },
});
export const routes = [route, responsesRoute];
export const configure = (input = {}) => {
    const { apiKey: _apiKey, auth: _auth, baseURL: endpoint, ...defaults } = input;
    const auth = AuthOptions.bearer(input, ["DIGITALOCEAN_ACCESS_TOKEN", "DIGITALOCEAN_API_KEY", "DO_INFERENCE_API_KEY"]);
    const options = { ...defaults, endpoint: { baseURL: endpoint ?? baseURL }, auth };
    const configured = route.with(options);
    const configuredResponses = responsesRoute.with(options);
    const decisionRoute = SystemOne.route.with({
        provider: id,
        providerMetadataKey: "digitalocean",
        endpoint: { baseURL: endpoint ?? baseURL },
        auth,
        // DigitalOcean serves TypeSafe's Jev, which needs this header for images.
        headers: { "TypeSafe-Danger-Zone-Images": "true", ...input.headers },
        http: input.http,
    });
    const decision = (modelID, providerOptions) => decisionRoute.model({ id: modelID, providerOptions });
    const media = MediaRoute.deployment({ ...input, baseURL: endpoint ?? baseURL }, auth);
    const image = (modelID, providerOptions) => OpenAIImages.model({ ...media, id: modelID, provider: id, providerOptions });
    return {
        id,
        model: (modelID) => configured.model({
            id: modelID,
            compatibility: {
                supportsPromptCacheKey: true,
            },
        }),
        responses: (modelID) => configuredResponses.model({ id: modelID }),
        image,
        decision,
        configure,
    };
};
export const provider = configure();
export const decision = provider.decision;
export const image = provider.image;
export const responses = provider.responses;
export const model = (modelID, settings) => configure(config(settings)).model(modelID);
export const responsesModel = (modelID, settings) => configure(config(settings)).responses(modelID);
export const imageModel = (modelID, settings) => {
    const input = config(settings);
    return configure(input).image(modelID, input.providerOptions);
};
export const decisionModel = (modelID, settings) => {
    const input = config(settings);
    return configure(input).decision(modelID, input.providerOptions);
};
function config({ apiKey, baseURL, body, headers, ...providerOptions } = {}) {
    return {
        apiKey,
        baseURL,
        headers,
        http: { body },
        providerOptions,
    };
}
export * as DigitalOcean from "./digitalocean.js";
